const deferredWebGpuAdaptivePixelRatio = new DeferredAdaptivePixelRatio();
const MATCH_ADMISSION_ADAPTIVE_WARMUP_SUBMISSIONS = 8;
const MATCH_ADMISSION_ADAPTIVE_SAMPLE_COUNT = 60;
